multi_queries.type_and_summary:
PREFIX hist: <http://www.example.org/korean-history#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entity ?entityLabel ?type ?summary ?category ?year WHERE {
    ?entity rdfs:label ?entityLabel .
    FILTER (?entityLabel = "훈민정음 창제" || ?entityLabel = "훈민정음" || ?entityLabel = "세종" || ?entityLabel = "정음 28자(훈민정음) 해석" || ?entityLabel = "훈민정음 서문" || ?entityLabel = "병자호란" || ?entityLabel = "창덕궁 감역관 임명 (1453)" || ?entityLabel = "명-일 감합무역" || ?entityLabel = "일본의 감합선 도항 (1404-1547)" || ?entityLabel = "계유정난")
    OPTIONAL { ?entity rdf:type ?type }
    OPTIONAL { ?entity hist:hasSummary ?summary }
    OPTIONAL { ?entity hist:hasCategory ?category }
    OPTIONAL { ?entity hist:hasYear ?year }
} LIMIT 50

